LINKS = []
SHARES = []


def entities(E):
    LINKS.clear(); SHARES.clear(); out=[]
    def add(s,kind,key,name,en,q,eq,cn,note='',**extra):
        suffix=s[4:]+s[2]
        out.append(E(s,kind,key+'-'+suffix,name,en,q,cn,eq,(eq+' '+note).strip(),**extra))
        return out[-1]['id']
    def product(s,key,name,en,q,eq,kind='material',**extra):
        mountain=next(r for r in ROWS if r['slug']==s)
        return add(s,kind,key,name+'（'+mountain['name']+'）',en+' ('+mountain['en_name']+')',q,eq,
                   '按本段物产原名、位置及经注层次分录，不强定现代种属、成分或坐标。',**extra)
    def products(s,items,kind='material'):
        for key,name,en,q,eq in items: product(s,key,name,en,q,eq,kind)
    def unknown(s,key,name,en,q,**extra):
        return add(s,'animal',key,name,en,q,en+' occurs in the account.',
                   '本段未给独立完整形貌，词义分合保留；不借他山郭注或现代物种补形。',
                   'Insufficient independent form evidence; the placeholder supplies no anatomy.',unknown=True,**extra)
    def jiang_share(s,q,eq):
        SHARES.append(('water-zhongshan-jiang-range9-nvfan9',s,q,eq))

    s='r08-huan'
    product(s,'tan','檀','Tan trees','其木多檀','Tan trees are abundant.','plant')
    product(s,'gui-stone','邽石','Gui stone','多邽石','Gui stone is abundant.')
    product(s,'white-tin','白錫','White tin','多白錫','White tin is abundant.',commentary='今白；鑞也',en_commentary='The white-la gloss continues across units 342–343; it does not specify modern alloy composition.')
    yu=add(s,'water','yu','郁水（讙山）','Yu water (Huan)','郁水出于其上潜于其下',
           'Yu water emerges above and disappears below.','上出下潜原文保留，未载受水体或流向，不编造现代暗河路线。')
    for key,n,en in [('di','砥','Di stones'),('li','礪','Li stones')]:
        stone=product(s,key,n+'（郁水）',en+' in Yu water','其中多砥礪',en+' are abundant in the water account.'); LINKS.append((yu,stone))
    s='r08-renju'
    products(s,[('gu','穀','Gu trees','其木多穀柞','Gu trees are abundant.'),('zuo','柞','Zuo trees','其木多穀柞','Zuo trees are abundant.')],'plant')
    products(s,[('red-metal','赤金','Red metal','其陽多赤金','Red metal is abundant on the sunny side.'),('ochre','赭','Ochre','其隂多赭','Ochre is abundant on the shaded side.')])
    s='r08-shimei'
    products(s,[('di','砥','Di stones','其陽多砥礪','Di stones occur on the sunny side.'),('li','礪','Li stones','其陽多砥礪','Li stones occur on the sunny side.'),('qinghu','青䨼','Qinghu','其隂多青䨼','Qinghu occurs on the shaded side.')])
    products(s,[('bai','栢','Bai trees','其木多栢','Bai trees are abundant.'),('tan','檀','Tan trees','多檀','Tan trees are abundant.'),('zhe','柘','Zhe trees','多柘','Zhe trees are abundant.'),('bamboo','竹','Bamboo','其草多竹','Bamboo occurs in the grass list.')],'plant')
    s='r08-qingu'
    products(s,[('gu','榖','Gu trees','其木多榖柞椒柘','Gu trees are abundant.'),('zuo','柞','Zuo trees','其木多榖柞椒柘','Zuo trees are abundant.'),('zhe','柘','Zhe trees','其木多榖柞椒柘','Zhe trees are abundant.')],'plant')
    product(s,'jiao','椒','Jiao trees','其木多榖柞椒柘','Jiao trees are abundant.','plant',commentary='椒為樹小；而叢生下有草木則蠚死',en_commentary='The gloss spans 348–349, describing small clustered trees and an ancient claim that vegetation beneath them dies; no modern botanical or toxicity determination is imposed.')
    products(s,[('white-min','白珉','White min','其上多白珉','White min is abundant above.'),('xi-stone','洗石','Xi stone','其下多洗石','Xi stone is abundant below.')])
    for key,n,en,q in [('pig','豕','Pigs','其獸多豕鹿'),('deer','鹿','Deer','其獸多豕鹿'),('white-xi','白犀','White xi beasts','多白犀'),('zhen','鴆','Zhen birds','其鳥多鴆')]: unknown(s,key,n+'（琴皷）',en+' (Qingu)',q)
    s='r08-summary'
    add(s,'deity','humanbird','次八山神（鸟身人面）','Eighth-range gods (bird body, human face)','其神狀皆鳥身而人面',
        'The gods have bird bodies and human faces.','鸟身人面据正文，图为完整鸟躯配人面，不画成人身长翼；鸟种、双足、翼尾布局、年龄、配色和姿态为艺术解释。',
        'The image keeps a full bird body and human face. Bird species, two legs, folded wings, tail design, age, colors and pose are artistic; no winged human torso is asserted.')
    for key,n,en,q,eq in [('rooster','雄雞','Rooster offering','其祠用一雄雞','The rite uses one rooster.'),('zaogui','藻圭','Zao-gui jade','用一藻圭','The rite uses one zao-gui jade.'),('tu-grain','稌','Tu grain','糈用稌','Tu grain is used.'),('burial','祈瘞','Prayer and burial','祈瘞','Prayer and burial are recorded.'),('jiao-rite','驕山专祀','Jiao-specific rite','驕山冡也其祠用羞酒少牢祈瘞嬰毛一璧','Mount Jiao has a separate wine and lesser-livestock rite with prayer, burial and a bi jade.')]:
        add(s,'rite',key,n+'（次八总括）',en+' (eighth summary)',q,eq,'总括礼制按原文分录；驕山专祀不代替一般山神祭礼，不把祭牲当作神形。',commentary='禱請已埋之也' if key=='burial' else '',en_commentary='Guo Pu glosses prayer followed by burial.' if key=='burial' else '')
    s='r09-nvfan'
    product(s,'stone-nie','石𣵀','Stone nie','其上多石𣵀','Stone nie is abundant above.')
    products(s,[('niu','杻','Niu trees','其木多杻橿','Niu trees are abundant.'),('jiang','橿','Jiang trees','其木多杻橿','Jiang trees are abundant.'),('ju','菊','Ju herbs','其草多菊𦬸','Ju herbs are abundant.'),('zhu','𦬸','Zhu herbs','其草多菊𦬸','Zhu herbs are abundant.')],'plant')
    luo=add(s,'water','luo','洛水（女凡入江账户）','Luo water (Nüfan-to-Jiang account)','洛水出焉東注于江',
            'Luo water rises here and flows east into the Jiang.','此洛水东注江，不强合前文洛水伊水系统；女凡山名依本段。')
    river=add(s,'water','jiang-range9','江（中次九水文文本索引）','Jiang (ninth-range textual index)','東注于江','Luo water flows east into the Jiang.',
              '分别存女凡洛水入江、岷山江水东北入海及后文各水入江上下文；同名字形不证明现代河道同一性。')
    LINKS.append((luo,river))
    xiong=product(s,'xionghuang','雄黃（水中）','Xionghuang in water','其中多雄黃','Xionghuang is abundant in the water account.',commentary='雄黃亦出水中',en_commentary='Guo Pu explicitly says xionghuang also occurs in water.'); LINKS.append((luo,xiong))
    for key,n,en in [('tiger','虎','Tigers'),('leopard','豹','Leopards')]:unknown(s,key,n+'（女凡）',en+' (Nüfan)','其獸多虎豹')
    s='r09-min'
    jiang_share(s,'江水出焉東北流注于海','Jiang water rises at Min and flows northeast into the sea.')
    sea=add(s,'water','sea','海（岷山江水受水体）','Sea (Min Jiang recipient)','東北流注于海','The Jiang flows northeast into the sea.','海仅作受水名目，不据郭注古县名换算现代河口。')
    LINKS.append((river,sea))
    turtle=unknown(s,'fine-turtle','良龜（岷山）','Fine turtles (Min)','其中多良龜',commentary='良善',en_commentary='Guo Pu glosses liang as fine or good; no detailed turtle form is supplied.')
    tuo=add(s,'beast','tuo','鼉（岷山江水）','Tuo (Min Jiang)','多鼉','Tuo are abundant in the water account.',
        '郭注似蜥蜴、大者二丈、有鳞彩，跨359—360连读；四足长尾、鳞纹、体色比例与姿态为艺术解释，不强定现代鳄种，不画剥皮或鼓。',
        'Lizard-like form, large size and patterned scales follow commentary. Four legs, tail proportions, scale motif, colors and pose are artistic, without a modern crocodilian determination.',
        water=True,commentary='似蜥蜴大者長；二丈有鱗彩皮可以冐皷',en_commentary='The gloss spans 359–360: lizard-like, large examples two zhang long, patterned scales and a historical skin use.')
    LINKS.extend([(river,turtle),(river,tuo)])
    products(s,[('gold','金','Gold','其上多金玉','Gold is abundant above.'),('jade','玉','Jade','其上多金玉','Jade is abundant above.'),('white-min','白珉','White min','其下多白珉','White min is abundant below.')])
    products(s,[('mei','梅','Mei trees','其木多梅棠','Mei trees are abundant.'),('tang','棠','Tang trees','其木多梅棠','Tang trees are abundant.')],'plant')
    for key,n,en,q in [('xi','犀','Xi beasts','其獸多犀象'),('elephant','象','Elephants','其獸多犀象'),('han','翰','Han birds','其鳥多翰鷩'),('bi','鷩','Bi birds','其鳥多翰鷩')]:
        unknown(s,key,n+'（岷山）',en+' (Min)',q,commentary='白翰赤鷩' if key in ['han','bi'] else '',en_commentary='White Han and red Bi are commentary color terms, without independent full anatomy.' if key in ['han','bi'] else '')
    add(s,'beast','kui-cattle','夔牛（岷山）','Kui cattle (Min)','多夔牛','Kui cattle are abundant.',
        '郭注蜀山中大牛、重数千斤及晋太兴古事为依据；按大牛形作图，双角四蹄、毛色比例及姿态为艺术解释，不补一足、雷鼓或大荒夔形。',
        'Commentary describes large cattle and a historical account. Two horns, four hooves, coat color, proportions and pose are artistic; no one-legged thunder creature is imported.',
        commentary='今蜀山中有大牛重數千斤名為䕫牛晉太興元年此牛出上；庸郡人弩射殺得三十八檐肉即爾雅所謂魏',en_commentary='The historical large-cattle gloss spans 361–362; its final captured Wei wording is retained without completing a missing text or imposing another creature form.')
    s='r09-lai'
    lai=add(s,'water','jiang-source','江水（崍山出水）','Jiang water rising at Lai','江水出焉東流注大江',
            'Jiang water rises here and flows east into the Great Jiang.','本段出水与大江受水索引分录，郭注南江不改正文名称；不并岷山与崌山出水账户。',commentary='卭來山今在漢嘉嚴道縣；南江水所自出也山有九折坂出㹮㹮似熊而黒白駮亦食銅鐵也',en_commentary='Guo Pu gives historical geography and a southern-Jiang source account; the same gloss describes Mo at a nine-turn slope.')
    great=add(s,'water','great-jiang','大江（次九受水索引）','Great Jiang (ninth-range recipient index)','東流注大江',
              'Lai Jiang water flows east into the Great Jiang.','受水名大江与各山出水分别保留，不以近名自动认定现代同一河道。')
